import{_ as o,o as t,a,ag as r}from"./chunks/framework.Do1Zayaf.js";const p=JSON.parse('{"title":"Roxie Deployment Topologies","description":"","frontmatter":{},"headers":[],"relativePath":"aidoc/roxie-kb/topologies.md","filePath":"aidoc/roxie-kb/topologies.md","lastUpdated":1779520499000}'),l={name:"aidoc/roxie-kb/topologies.md"};function i(s,e,n,c,g,d){return t(),a("div",null,e[0]||(e[0]=[r('<h1 id="roxie-deployment-topologies" tabindex="-1">Roxie Deployment Topologies <a class="header-anchor" href="#roxie-deployment-topologies" aria-label="Permalink to &quot;Roxie Deployment Topologies&quot;">​</a></h1><blockquote><p><strong>Note</strong>: Roxie must perform reliably across vastly different physical footprints. When optimizing or tracing code, always consider the impact against these three primary production configurations.</p></blockquote><h2 id="topology-a-massive-scale-interactive-hot" tabindex="-1">Topology A: Massive Scale Interactive (Hot) <a class="header-anchor" href="#topology-a-massive-scale-interactive-hot" aria-label="Permalink to &quot;Topology A: Massive Scale Interactive (Hot)&quot;">​</a></h2><ul><li><strong>Scale</strong>: 100 nodes, 50 channels, 2 replicas per channel.</li><li><strong>Storage</strong>: Each worker manages access to ~10TB of index data stored on local NVME.</li><li><strong>Profile</strong>: <strong>Interactive / Hot Cache</strong>.</li><li><strong>Bottleneck Risks</strong>: Network incast (Server-to-Worker and Worker-to-Server scaling), cross-node message sorting, locking on globally shared memory mechanisms like <code>roxiemem</code>, and NVME I/O saturation.</li></ul><h2 id="topology-b-single-vm-interactive-hot" tabindex="-1">Topology B: Single-VM Interactive (Hot) <a class="header-anchor" href="#topology-b-single-vm-interactive-hot" aria-label="Permalink to &quot;Topology B: Single-VM Interactive (Hot)&quot;">​</a></h2><ul><li><strong>Scale</strong>: 20 nodes, 10 channels, 2 replicas per channel. <em>All nodes run on the same virtual machine.</em></li><li><strong>Storage</strong>: 10-20TB total index size stored on local NVME.</li><li><strong>Profile</strong>: <strong>Interactive / Hot Cache</strong>.</li><li><strong>Bottleneck Risks</strong>: Extreme OS context-switching, CPU cache trashing, and hypervisor limits. Since all 20 nodes share the exact same physical memory bus and CPU threads, synchronization locks (like <code>groupsCrit</code> or <code>heapletLock</code>) or thread-heavy operations will severely throttle the entire VM simultaneously.</li></ul><h2 id="topology-c-ephemeral-remote-batch-cold" tabindex="-1">Topology C: Ephemeral Remote / Batch (Cold) <a class="header-anchor" href="#topology-c-ephemeral-remote-batch-cold" aria-label="Permalink to &quot;Topology C: Ephemeral Remote / Batch (Cold)&quot;">​</a></h2><ul><li><strong>Scale</strong>: 10 nodes, 10 channels, 1 replica.</li><li><strong>Storage</strong>: ~200TB total data stored heavily on Remote Storage (e.g., S3, Azure Blob, etc.).</li><li><strong>Profile</strong>: <strong>Batch / Cold Cache</strong>.</li><li><strong>Bottleneck Risks</strong>: The cluster is dynamically provisioned, executes from cold-start, and quickly tears down. Startup speeds (e.g. <code>lazyOpen</code>, phase-split parallel query loading), massive initial I/O latency, and caching warm-up are the limiting factors. CPU bounds are less of an issue compared to remote storage block-read latencies.</li></ul>',8)]))}const m=o(l,[["render",i]]);export{p as __pageData,m as default};
